'use strict';
const KEY='kusa.workspace.v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)+'-'+Math.random().toString(36).slice(2);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const paths={folder:'M3 7h6l2-3h5l2 3h3v13H3z',chat:'M4 4h16v12H9l-5 4z',tasks:'M5 3h14v18H5z M8 11l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M12 19V5 M5 12l7-7 7 7',chevron:'M9 5l7 7-7 7',down:'M5 9l7 7 7-7',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',close:'M6 6l12 12 M18 6L6 18',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',edit:'M4 20l5-1L20 8l-5-5L4 14z M12 6l5 5',menu:'M4 6h16 M4 12h16 M4 18h16',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 18h.01',back:'M14 5l-7 7 7 7',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const files=n=>n+(n===1?' file':' files');
const folder=mini=>`<span class="folder-ic ${mini?'mini':''}" aria-hidden="true">${icon('folder')}</span>`;
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const WORKSPACES={personal:{name:'Personal',description:'One place for quick notes, files, and everyday plans.'},education:{name:'Education',description:'Subjects, study materials, class schedules, and academic deadlines.'},finance:{name:'Finance',description:'Keep financial records, bills, goals, and reports together.'},business:{name:'Business',description:'Organize company records, projects, and deadlines.'}};
const EDUCATION_SUBJECTS=['Mathematics','Science','English','Filipino','History','Computer Studies'];
const EDUCATION_SECTIONS=['Notes and Lectures','Modules and Learning Materials','Research Papers','Projects and Presentations','Books and References','Class Schedules','Academic Deadlines','Online Courses and Certificates'];
const FINANCE_FOLDERS=['Bills and Utilities','Budget and Budget Plans','Expenses and Receipts','Income and Salary Records','Savings Goals','Debts and Loans','Bank Statements','Investments','Stocks and Asset Records','Insurance Policies','Taxes and Tax Documents','Subscriptions and Recurring Payments','Payment Tracking','Financial Goals','Financial Reports','Business Financial Documents'];
const BUSINESS_FOLDERS=['Meetings and Meeting Minutes','Tasks and Projects','Payroll and Payroll Schedules','Employee Records','Inventory and Stock Management','Sales Reports','Customers and Clients','Invoices and Receivables','Contracts and Agreements','Business Permits and Licenses','Business Plans','Company Policies','Deliveries and Orders','Business Deadlines','Financial Reports'];
function seed(){return {version:1,demo:true,name:'Carl',model:'qwen2.5:3b',theme:'light',folders:[{id:'programming',name:'Programming'},{id:'history',name:'Philippine History'},{id:'math',name:'Mathematics'},{id:'general',name:'General'}],documents:[{id:uid(),folder:'programming',name:'Sample activity brief.txt',pages:[{number:1,text:'SAMPLE DOCUMENT — Demonstration only. Programming activity: Create a C++ program that reads two numbers and displays their sum. Submit your C++ source file, a screenshot of the output, and a short explanation of your solution. No submission deadline has been specified.'}]}],tasks:[{id:uid(),folder:'programming',title:'Complete the programming exercise',date:today(),time:'15:00',done:false},{id:uid(),folder:'history',title:'Write the history reflection',date:today(),time:'17:00',done:false},{id:uid(),folder:'math',title:'Finish the worksheet',date:today(),time:'20:00',done:false}],schedule:[{id:uid(),folder:'programming',title:'Programming',date:today(),start:'09:00',end:'10:30'},{id:uid(),folder:'history',title:'Philippine History',date:today(),start:'13:00',end:'14:30'}],chats:{},money:[]};}
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&Array.isArray(saved.folders)?saved:seed();}catch{state=seed();}
function folderUsed(s,id){return s.documents.some(x=>x.folder===id)||s.tasks.some(x=>x.folder===id)||s.schedule.some(x=>x.folder===id)||(s.chats[id]||[]).length>0;}
function ensureEducationSections(s,subject){for(const name of EDUCATION_SECTIONS){const key=subject.id+'::'+name;const child=s.folders.find(f=>f.workspace==='education'&&f.parentId===subject.id&&(f.educationSection===name||f.name===name));if(child){child.educationSection=name;s.deletedEducationSections=s.deletedEducationSections.filter(x=>x!==key);}else if(!s.deletedEducationSections.includes(key))s.folders.push({id:uid(),name,workspace:'education',parentId:subject.id,educationSection:name});}}
function migrate(s){
 for(const f of s.folders)if(!WORKSPACES[f.workspace])f.workspace=f.id==='general'?'personal':f.id==='finance'?'finance':f.id==='business'?'business':'education';
 if(!s.chats||typeof s.chats!=='object')s.chats={};
 for(const k of ['documents','tasks','schedule'])if(!Array.isArray(s[k]))s[k]=[];
 if(!Array.isArray(s.money))s.money=[];
 if(!['light','dark','system'].includes(s.theme))s.theme='light';
 for(const k of ['deletedEducationSubjects','deletedEducationSections','deletedFinanceAreas','deletedBusinessAreas'])if(!Array.isArray(s[k]))s[k]=[];
 if(!s.folders.some(f=>f.workspace==='personal'))s.folders.push({id:uid(),name:'General',workspace:'personal'});
 if(s.demo){for(const f of s.folders){if(f.workspace==='education'&&f.id==='programming'){f.name='Computer Studies';f.educationSubject='Computer Studies';}else if(f.workspace==='education'&&f.id==='history'){f.name='History';f.educationSubject='History';}else if(f.workspace==='education'&&f.id==='math'){f.name='Mathematics';f.educationSubject='Mathematics';}}}
 for(const [ws,oldName,newName] of [['education','Education','General'],['finance','Finance','General finance files'],['business','Business','General business files']])for(const f of [...s.folders])if(f.workspace===ws&&!f.parentId&&f.name===oldName&&!f.educationSubject&&!f.financeArea&&!f.businessArea){if(folderUsed(s,f.id)){f.name=newName;if(ws!=='education')f.archived=true;}else s.folders=s.folders.filter(x=>x!==f);}
 for(const name of EDUCATION_SUBJECTS){let subject=s.folders.find(f=>f.workspace==='education'&&!f.parentId&&(f.educationSubject===name||f.name===name));if(subject){subject.educationSubject=name;s.deletedEducationSubjects=s.deletedEducationSubjects.filter(x=>x!==name);}else if(!s.deletedEducationSubjects.includes(name))subject={id:uid(),name,workspace:'education',educationSubject:name},s.folders.push(subject);if(subject)ensureEducationSections(s,subject);}
 for(const subject of s.folders.filter(f=>f.workspace==='education'&&!f.parentId)){if(subject.educationSubject&&!EDUCATION_SUBJECTS.includes(subject.educationSubject))continue;ensureEducationSections(s,subject);}
 for(const [name,marker,deleted] of [...FINANCE_FOLDERS.map(name=>[name,'financeArea','deletedFinanceAreas']),...BUSINESS_FOLDERS.map(name=>[name,'businessArea','deletedBusinessAreas'])]){const ws=marker==='financeArea'?'finance':'business';const list=s[deleted];const existing=s.folders.find(f=>f.workspace===ws&&(f[marker]===name||(!f.parentId&&f.name===name)));if(existing){existing[marker]=name;list.splice(0,list.length,...list.filter(x=>x!==name));}else if(!list.includes(name))s.folders.push({id:uid(),name,workspace:ws,[marker]:name});}
 for(const f of s.folders)if(f.workspace==='business'&&['Suppliers and Vendors','Marketing and Advertising','Operational Reports'].includes(f.businessArea||f.name))f.archived=true;
 return s;
}
migrate(state);
function folderUnavailable(f){let current=f;while(current){if(current.archived)return true;current=current.parentId?state.folders.find(x=>x.id===current.parentId):null;}return false;}
function applyTheme(){const theme=state.theme==='system'?(window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme;document.documentElement.dataset.theme=theme;}
applyTheme();
function createEducationSubject(name){const existing=state.folders.find(f=>f.workspace==='education'&&!f.parentId&&f.name.toLowerCase()===name.toLowerCase());if(existing)return existing;const standard=EDUCATION_SUBJECTS.find(x=>x.toLowerCase()===name.toLowerCase());const subject={id:uid(),name,workspace:'education',...(standard?{educationSubject:standard}:{})};if(standard)state.deletedEducationSubjects=state.deletedEducationSubjects.filter(x=>x!==standard);state.folders.push(subject);ensureEducationSections(state,subject);return subject;}
const lanHost=/^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)/.test(location.hostname);
const localBackend=['localhost','127.0.0.1'].includes(location.hostname)||lanHost;
const lanTokenKey='kusa.lan.token.'+location.host;
let backendToken=localStorage.getItem(lanTokenKey)||'';
const pairToken=new URLSearchParams(location.search).get('pair');
if(lanHost&&pairToken){backendToken=pairToken;localStorage.setItem(lanTokenKey,pairToken);history.replaceState(null,'',location.pathname+location.hash);}
const paired=!lanHost||!!backendToken;
let workspace='personal',page='projects',tab='documents',activeFolder=null,chatFolder=state.folders.find(f=>f.workspace==='personal')?.id||state.folders[0]?.id||'',filter='open',busy=false,status=localBackend?{checking:true,connected:false,models:[]}:{unsupportedHost:true};
const visibleFolders=()=>state.folders.filter(f=>f.workspace===workspace&&!folderUnavailable(f));
const workspaceFor=folderId=>state.folders.find(f=>f.id===folderId)?.workspace||'personal';
const workspaceTabs=()=>`<div class="ws-tabs" role="tablist" aria-label="Workspace">${Object.entries(WORKSPACES).map(([id,w])=>`<button role="tab" aria-selected="${workspace===id}" data-action="workspace" data-workspace="${id}" class="${workspace===id?'active':''} ${anim.ws&&workspace===id?'glow':''}">${w.name}</button>`).join('')}</div>`;
function routeRequest(question){
 const match=question.trim().match(/^(?:put|move|file)\s+(?:this\s+)?(.+?)\s+(?:in|into|to)\s+(?:my\s+)?(personal|education|finance|business)(?:\s+workspace)?[.!?]?$/i);
 if(!match)return false;
 const destination=match[2].toLowerCase(),query=match[1].replace(/^(?:the|these)\s+/i,'').toLowerCase();
 const docs=state.documents.filter(d=>!d.archived&&d.name.toLowerCase().includes(query)&&workspaceFor(d.folder)===workspace);
 if(docs.length!==1){toast(docs.length?'Several files match. Open Documents and use Move on the right file.':'I could not find that file here. Try part of its exact filename.');return true;}
 const doc=docs[0],folders=state.folders.filter(f=>f.workspace===destination&&!folderUnavailable(f));
 modal('Move file?',`<form><p class="inline-help">Move ${esc(doc.name)} to ${WORKSPACES[destination].name}? Its contents and saved chat remain on this device.</p><label class="field">Destination folder<select name="folder">${folders.map(f=>`<option value="${esc(f.id)}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>${actions('Move')}</form>`,e=>{e.preventDefault();doc.folder=new FormData(e.target).get('folder');persist();$('#modal').close();render();toast('File moved to '+WORKSPACES[destination].name+'.');});
 return true;
}
const chatKey=()=>chatFolder;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Storage is full. Export a backup and remove large files. Your last change is not saved.');return false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
const findFolder=id=>state.folders.find(f=>f.id===id)?.name||'General';
const folderPath=id=>{const f=state.folders.find(x=>x.id===id);if(!f)return'General';const parent=f.parentId?state.folders.find(x=>x.id===f.parentId):null;return parent?`${parent.name} / ${f.name}`:f.name;};
function formatTime(t){if(!t)return 'Any time';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`;}
const folderOptions=(selected,all=false)=>all?Object.entries(WORKSPACES).map(([id,w])=>{const fs=state.folders.filter(f=>f.workspace===id&&!folderUnavailable(f));return fs.length?`<optgroup label="${esc(w.name)}">${fs.map(f=>`<option value="${esc(f.id)}" ${f.id===selected?'selected':''}>${esc(folderPath(f.id))}</option>`).join('')}</optgroup>`:'';}).join(''):visibleFolders().map(f=>`<option value="${esc(f.id)}" ${f.id===selected?'selected':''}>${esc(folderPath(f.id))}</option>`).join('');
function logo(){return '<span class="brand"><img src="assets/logo-transparent.png" alt="Kusa"></span>';}
function nav(){return `<nav class="nav" aria-label="Main navigation">${[['projects','folder','Projects'],['chat','k','Ask Kusa'],['tasks','tasks','Tasks'],['settings','settings','Settings']].map(([p,i,l])=>`<button data-action="nav" data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${i==='k'?'<span class="k-icon">K</span>':icon(i)}<span>${l}</span></button>`).join('')}</nav>`;}
function header(){return `<header class="header">${logo()}<button class="avatar" data-action="nav" data-page="settings" aria-label="Open settings">${esc((state.name||'Me').slice(0,2).toUpperCase())}</button></header>`;}
let anim={},last={};
function render(){const tabKey=tab+':'+(activeFolder||'');anim={page:page!==last.page,ws:page===last.page&&workspace!==last.ws,tab:page===last.page&&workspace===last.ws&&tabKey!==last.tab};last={page,ws:workspace,tab:tabKey};$('#app').innerHTML=page==='chat'?chatView():`<div class="shell">${header()}${page==='projects'?projectsView():page==='tasks'?tasksView():settingsView()}</div>${nav()}`;if(anim.page)$('.shell').classList.add('page-enter');if(page==='chat'){$('.chat-body').scrollTop=$('.chat-body').scrollHeight;}}
function tasksGroup(folderId,items){return `<details class="card subject" open><summary>${folder(true)}<strong>${esc(findFolder(folderId))}</strong><small>${items.filter(t=>t.done).length}/${items.length}</small>${icon('down')}</summary>${items.length?items.map(t=>`<div class="task-row ${t.done?'done':''}"><input type="checkbox" id="task-${t.id}" data-task="${t.id}" ${t.done?'checked':''} aria-label="Complete ${esc(t.title)}"><label for="task-${t.id}">${esc(t.title)}${t.date?`<small>${esc(t.date)}${t.time?' · '+formatTime(t.time):''}</small>`:''}</label><button class="icon-btn" data-action="edit-task" data-id="${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button></div>`).join(''):'<div class="empty">No tasks here yet.</div>'}</details>`;}
function dateOffset(days){const d=new Date();d.setDate(d.getDate()+days);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function addDemoData(){const available=(ws,name)=>state.folders.find(f=>f.workspace===ws&&f.name===name&&!folderUnavailable(f));const personal=state.folders.find(f=>f.workspace==='personal'&&!f.parentId&&!folderUnavailable(f))||state.folders.find(f=>f.workspace==='personal'&&!folderUnavailable(f));const science=available('education','Science');const scienceNotes=science&&state.folders.find(f=>f.parentId===science.id&&f.name==='Notes and Lectures'&&!folderUnavailable(f));const finance=available('finance','Expenses and Receipts');const business=available('business','Meetings and Meeting Minutes');const first=ws=>state.folders.find(f=>f.workspace===ws&&!folderUnavailable(f));const dest={personal:personal?.id,education:scienceNotes?.id||science?.id||first('education')?.id,finance:finance?.id||first('finance')?.id,business:business?.id||first('business')?.id};
 const docs=[['demo-sort-report',dest.personal,'DEMO - Quick sort report.txt','Sample file for testing Quick file sorting. In Ask Kusa, type: Move DEMO - Quick sort report.txt to Finance. Kusa will ask you to confirm a destination.'],['demo-science-notes',dest.education,'DEMO - Science notes.txt','The water cycle has four main stages: evaporation, condensation, precipitation, and collection. Heat from the Sun causes water to evaporate. Water vapor cools and condenses into clouds. It returns to Earth as precipitation.'],['demo-finance-receipt',dest.finance,'DEMO - Grocery receipt.txt','DEMO ONLY. Date: Today. Groceries: PHP 850.00. Fictional sample text for testing document organization.'],['demo-business-minutes',dest.business,'DEMO - Meeting minutes.txt','DEMO ONLY. Meeting: Weekly team check-in. Decisions: review pending customer orders, count low-stock items, and prepare next week sales summary.']];
 for(const [id,folderId,name,text] of docs)if(folderId&&!state.documents.some(x=>x.id===id))state.documents.push({id,folder:folderId,name,pages:[{number:1,text}]});
 const tasks=[['demo-task-personal-today',dest.personal,'DEMO: Sort the project brief',0,'10:00'],['demo-task-personal-upcoming',dest.personal,'DEMO: Review saved notes',1,'15:00'],['demo-task-education-today',dest.education,'DEMO: Review the water cycle notes',0,'16:00'],['demo-task-education-upcoming',dest.education,'DEMO: Submit the science reflection',2,'17:00'],['demo-task-finance-today',dest.finance,'DEMO: Categorize grocery expenses',0,'13:00'],['demo-task-finance-upcoming',dest.finance,'DEMO: Review the monthly budget',2,'18:00'],['demo-task-business-today',dest.business,'DEMO: Prepare the team meeting agenda',0,'14:00'],['demo-task-business-upcoming',dest.business,'DEMO: Check the sample inventory list',3,'16:00']];
 for(const [id,folderId,title,days,time] of tasks)if(folderId&&!state.tasks.some(x=>x.id===id))state.tasks.push({id,folder:folderId,title,date:dateOffset(days),time,done:false});
 const schedules=[['demo-schedule-personal',dest.personal,'DEMO: Planning time','09:00','09:30'],['demo-schedule-education',dest.education,'DEMO: Science study session','11:00','12:00'],['demo-schedule-finance',dest.finance,'DEMO: Budget review','13:30','14:00'],['demo-schedule-business',dest.business,'DEMO: Team check-in','15:00','15:30']];
 for(const [id,folderId,title,start,end] of schedules)if(folderId&&!state.schedule.some(x=>x.id===id))state.schedule.push({id,folder:folderId,title,date:dateOffset(0),start,end});
 for(const [id,kind,amount,note] of [['demo-money-income','income',25000,'DEMO salary'],['demo-money-expense','expense',850,'DEMO groceries']])if(!state.money.some(x=>x.id===id))state.money.push({id,kind,amount,note,date:dateOffset(0)});
 state.demo=true;persist();render();toast('Labeled demo records added across your workspaces.');}
function dayTimeline(){const now=today();const items=[...state.schedule.filter(s=>workspaceFor(s.folder)===workspace&&s.date===now).map(s=>({id:s.id,time:s.start,title:s.title,folder:s.folder,kind:'schedule'})),...state.tasks.filter(t=>workspaceFor(t.folder)===workspace&&t.date===now&&!t.done).map(t=>({id:t.id,time:t.time,title:t.title,folder:t.folder,kind:'task'}))].sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));const shown=items.slice(0,6);return `<section class="card day-card"><div class="day-head"><span>Today in ${esc(WORKSPACES[workspace].name)}</span><span class="badge">${items.length}</span></div>${shown.length?shown.map(x=>`<button class="day-row" data-action="${x.kind==='schedule'?'edit-schedule':'edit-task'}" data-id="${esc(x.id)}"><time>${formatTime(x.time)}</time><span class="day-text"><strong>${esc(x.title)}</strong><small>${esc(findFolder(x.folder))}${x.kind==='task'?' · due':''}</small></span></button>`).join(''):`<p class="empty">Nothing scheduled or due today in ${esc(WORKSPACES[workspace].name)}.</p>`}${items.length>shown.length?`<p class="day-more">+${items.length-shown.length} more today</p>`:''}</section>`;}
function projectsView(){return `${workspaceTabs()}<div class="heading"><div><h1>${activeFolder?esc(findFolder(activeFolder)):WORKSPACES[workspace].name+' workspace'}</h1><p>${new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p></div>${activeFolder?btn(icon('back')+' Back','back-folders','small'):''}</div><div class="ws-body ${anim.ws?'page-enter':''}">${!activeFolder?`<p class="workspace-description">${WORKSPACES[workspace].description}</p><h2 class="section-label">Overview</h2>${!activeFolder?'<div class="sample"><span>'+(state.demo?'Demo records are labeled DEMO. They are examples for testing.':'Add labeled demo files, tasks, schedules, and expenses to explore Kusa.')+'</span><div class="sample-actions"><button class="sample-load" data-action="load-demo">Load demo data</button>'+(state.demo?'<button class="sample-clear" data-action="clear-sample">Start fresh</button>':'')+'</div></div>':''}${dayTimeline()}${overview()}`:''}<div class="tabs" role="tablist">${['documents','tasks'].map(t=>`<button role="tab" aria-selected="${tab===t}" data-action="tab" data-tab="${t}" class="${tab===t?'active':''} ${anim.tab&&tab===t?'glow':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="tab-body ${anim.tab?'page-enter':''}">${tab==='tasks'?tasksView(true):documentsView()}</div></div>`;}
function overview(){let now=today();let due=state.tasks.filter(t=>workspaceFor(t.folder)===workspace&&t.date===now&&!t.done).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));let upcoming=state.tasks.filter(t=>workspaceFor(t.folder)===workspace&&t.date&&t.date!==now&&!t.done).sort((a,b)=>(a.date+' '+(a.time||'99')).localeCompare(b.date+' '+(b.time||'99'))).slice(0,5);let classes=state.schedule.filter(s=>workspaceFor(s.folder)===workspace&&s.date===now).sort((a,b)=>a.start.localeCompare(b.start));return `<div class="workspace-grid">${workspace==='finance'?financeOverview():''}${workspace==='personal'?'<section class="card quick-tip"><div><h2>Quick file sorting</h2><p>Upload a PDF, TXT, or Markdown file to your Personal inbox. Then in Ask Kusa, type: “Move [filename] to Finance.” Kusa will ask you to confirm the destination.</p></div><button class="btn primary small" data-action="quick-upload">Upload a file</button></section>':''}<section class="section"><div class="section-top"><h2>${workspace==='business'?'Today at work':'Today'}</h2>${btn(icon('plus')+' Schedule','add-schedule','small')}</div><div class="card today-card"><div class="today-sub"><div class="label">${icon('calendar')} ${workspace==='education'?'Class schedule':'Schedule'}</div>${classes.length?classes.map(s=>`<div class="schedule-row"><span class="schedule-time">${formatTime(s.start)}<br>${formatTime(s.end)}</span><div class="schedule-content">${esc(s.title)}<small>${esc(findFolder(s.folder))}</small></div><button class="icon-btn" data-action="edit-schedule" data-id="${s.id}" aria-label="Edit ${esc(s.title)}">${icon('edit')}</button></div>`).join(''):'<p class="empty">Nothing scheduled today.</p>'}</div><div class="today-sub"><div class="label">${icon('file')} Due today <span class="badge">${due.length}</span></div><div class="timeline">${due.length?due.map(t=>`<div class="deadline"><time>${formatTime(t.time)}</time><div><button data-action="edit-task" data-id="${t.id}" style="padding:0;text-align:left">${esc(t.title)}</button><small>${esc(findFolder(t.folder))}</small></div></div>`).join(''):'<p class="empty">No pending deadlines today.</p>'}</div></div></div></section><section class="section"><div class="section-top"><h2>Upcoming deadlines</h2><button class="text-btn" data-action="add-task">+ Task</button></div><div class="card upcoming-card">${upcoming.length?`<div class="upcoming-list">${upcoming.map(t=>`<div class="upcoming-row"><div class="upcoming-when">${t.date<now?`<span class="overdue-tag">Overdue</span><small>${esc(t.date)}</small>`:`<time>${esc(t.date)}</time>`}${t.time?`<small>${formatTime(t.time)}</small>`:''}</div><div class="upcoming-detail"><button class="upcoming-title" data-action="edit-task" data-id="${t.id}"><strong>${esc(t.title)}</strong></button><small>${esc(folderPath(t.folder))}</small></div></div>`).join('')}</div>`:'<p class="empty">Nothing coming up yet. Add a due date to a task to see it here.</p>'}</div></section></div>`;}
function financeOverview(){const entries=state.money.filter(x=>x&&typeof x.amount==='number'&&Number.isFinite(x.amount));const sum=kind=>entries.filter(x=>x.kind===kind).reduce((total,x)=>total+x.amount,0);const money=n=>'₱'+n.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});return `<section class="section"><div class="section-top"><h2>Money overview</h2>${btn(icon('plus')+' Entry','add-money','primary small')}</div><div class="finance-stats"><div class="card"><small>Income</small><strong>${money(sum('income'))}</strong></div><div class="card"><small>Expenses</small><strong>${money(sum('expense'))}</strong></div><div class="card"><small>Balance</small><strong>${money(sum('income')-sum('expense'))}</strong></div></div><div class="card">${entries.length?entries.slice(-5).reverse().map(x=>`<div class="file-row"><strong>${esc(x.note)}</strong><small>${esc(x.date)} · ${x.kind==='income'?'+':'−'}${money(x.amount)}</small><button class="icon-btn" data-action="delete-money" data-id="${esc(x.id)}" aria-label="Delete entry">${icon('trash')}</button></div>`).join(''):'<p class="empty">Add income or an expense to start tracking here.</p>'}</div><p class="save-note">Manual entries only. Kusa does not connect to a bank.</p></section>`;}
function descendantIds(id){const ids=[id];for(let i=0;i<ids.length;i++)for(const f of state.folders)if(f.parentId===ids[i]&&!ids.includes(f.id))ids.push(f.id);return ids;}
function folderCard(f,archived=false){const n=state.documents.filter(d=>d.folder===f.id&&!d.archived).length;return `<div class="card folder-card ${archived?'is-archived':''}">${archived?`<div class="folder-main folder-static">${folder(false)}<span><strong>${esc(f.name)}</strong><small>Archived · ${files(n)}</small></span></div>`:`<button class="folder-main" data-action="open-folder" data-id="${esc(f.id)}">${folder(false)}<span><strong>${esc(f.name)}</strong><small>${files(n)}</small></span>${icon('chevron','chevron')}</button>`}<details class="folder-menu"><summary aria-label="Options for ${esc(f.name)}" title="Folder options">···</summary><div class="folder-menu-popover"><button data-action="rename-folder" data-id="${esc(f.id)}">Rename</button><button data-action="archive-folder" data-id="${esc(f.id)}">${archived?'Restore':'Archive'}</button><button class="menu-danger" data-action="delete-folder" data-id="${esc(f.id)}">Delete</button></div></details></div>`;}
function folderGrid(parentId=activeFolder){const siblings=state.folders.filter(f=>f.workspace===workspace&&(f.parentId||null)===(parentId||null));const active=siblings.filter(f=>!folderUnavailable(f));const archived=siblings.filter(f=>f.archived&&!folderUnavailable(f.parentId?state.folders.find(x=>x.id===f.parentId):null));return `${active.length?`<div class="folder-grid">${active.map(f=>folderCard(f)).join('')}</div>`:'<div class="card empty">No active folders here. Restore an archived folder or create a folder.</div>'}${archived.length?`<details class="archived-folders"><summary>Archived folders <span class="badge">${archived.length}</span></summary><div class="folder-grid">${archived.map(f=>folderCard(f,true)).join('')}</div></details>`:''}`;}
function deleteFolderPrompt(id){const f=state.folders.find(x=>x.id===id);if(!f)return;const ids=descendantIds(id),has=x=>ids.includes(x.folder);const docs=state.documents.filter(has).length,tasks=state.tasks.filter(has).length,schedule=state.schedule.filter(has).length,chats=ids.reduce((n,x)=>(n+(state.chats[x]||[]).length),0),total=docs+tasks+schedule+chats,targets=visibleFolders().filter(x=>!ids.includes(x.id));if(!total){modal('Delete folder?',`<p class="inline-help">Delete “${esc(f.name)}”? This folder is empty.</p><div class="form-actions">${btn('Cancel','close-modal')}${btn('Delete folder','confirm-delete-folder','danger',`type="button" data-id="${esc(id)}"`)}</div>`);return;}const summary=[docs?`${docs} file${docs===1?'':'s'}`:'',tasks?`${tasks} task${tasks===1?'':'s'}`:'',schedule?`${schedule} schedule entr${schedule===1?'y':'ies'}`:'',chats?`${chats} chat message${chats===1?'':'s'}`:''].filter(Boolean).join(', ');modal('Delete folder?',`<form><p class="inline-help">“${esc(f.name)}” contains ${esc(summary)}${ids.length>1?' across its subfolders':''}. Choose a folder to move its contents to and keep them.</p>${targets.length?`<label class="field">Move contents to<select name="destination">${targets.map(x=>`<option value="${esc(x.id)}">${esc(folderPath(x.id))}</option>`).join('')}</select></label>`:'<p class="inline-help">There is no other active folder in this workspace. Create one first to keep this content.</p>'}<div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" ${targets.length?'':'disabled'}>Move contents and delete folder</button></div><div class="form-actions"><button type="button" class="btn danger" data-action="confirm-delete-folder" data-id="${esc(id)}">Permanently delete folder and contents</button></div></form>`,e=>{e.preventDefault();const destination=new FormData(e.target).get('destination');if(!destination)return;removeFolder(id,destination,false);});}
function confirmPermanentFolderDelete(id){const f=state.folders.find(x=>x.id===id);if(!f)return;modal('Permanently delete?',`<p class="inline-help">Permanently delete “${esc(f.name)}” and everything inside it, including files, tasks, schedules, and chat history? This cannot be undone.</p><div class="form-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" data-action="delete-folder-permanently" data-id="${esc(id)}">Delete permanently</button></div>`);}
function removeFolder(id,destination,permanent){const ids=descendantIds(id),removed=state.folders.filter(x=>ids.includes(x.id));for(const f of removed){if(f.educationSubject&&!state.deletedEducationSubjects.includes(f.educationSubject))state.deletedEducationSubjects.push(f.educationSubject);if(f.educationSection){const key=f.parentId+'::'+f.educationSection;if(!state.deletedEducationSections.includes(key))state.deletedEducationSections.push(key);}for(const [marker,list] of [['financeArea',state.deletedFinanceAreas],['businessArea',state.deletedBusinessAreas]])if(f[marker]&&!list.includes(f[marker]))list.push(f[marker]);}if(destination){for(const list of [state.documents,state.tasks,state.schedule])for(const item of list)if(ids.includes(item.folder))item.folder=destination;for(const oldId of ids)if(state.chats[oldId]?.length)state.chats[destination]=[...(state.chats[destination]||[]),...state.chats[oldId]];}else{state.documents=state.documents.filter(x=>!ids.includes(x.folder));state.tasks=state.tasks.filter(x=>!ids.includes(x.folder));state.schedule=state.schedule.filter(x=>!ids.includes(x.folder));}for(const oldId of ids)delete state.chats[oldId];state.folders=state.folders.filter(x=>!ids.includes(x.id));if(ids.includes(activeFolder))activeFolder=null;if(ids.includes(chatFolder))chatFolder=destination||visibleFolders()[0]?.id||'';persist();$('#modal').close();render();toast(permanent?'Folder and contents deleted.':'Folder deleted; contents moved.');}
function documentRow(d,archived=false){return `<div class="file-row ${archived?'is-archived':''}"><span class="file-symbol">${icon('file')}</span><button class="file-open" data-action="view-doc" data-id="${esc(d.id)}"><strong>${esc(d.name)}</strong><small>${d.pages.length} ${d.name.toLowerCase().endsWith('.pdf')?'pages':'section(s)'} · ${esc(folderPath(d.folder))}${archived?' · Archived':''}</small></button><details class="folder-menu document-menu"><summary aria-label="Options for ${esc(d.name)}" title="Document options">···</summary><div class="folder-menu-popover"><button data-action="rename-document" data-id="${esc(d.id)}">Rename</button><button data-action="move-doc" data-id="${esc(d.id)}">Move</button><button data-action="archive-document" data-id="${esc(d.id)}">${archived?'Restore':'Archive'}</button><button class="menu-danger" data-action="delete-doc" data-id="${esc(d.id)}">Delete</button></div></details></div>`;}
function documentsView(){const docs=state.documents.filter(d=>!d.archived&&(activeFolder?d.folder===activeFolder:workspaceFor(d.folder)===workspace));const scopeIds=activeFolder?descendantIds(activeFolder):state.folders.filter(f=>f.workspace===workspace).map(f=>f.id);const archivedDocs=state.documents.filter(d=>d.archived&&scopeIds.includes(d.folder));const hasChildren=!!activeFolder&&state.folders.some(f=>f.workspace===workspace&&f.parentId===activeFolder);const showFolders=!activeFolder||hasChildren;const folderTitle=workspace==='education'&&!activeFolder?'Subjects':workspace==='finance'&&!activeFolder?'Financial folders':workspace==='business'&&!activeFolder?'Business folders':'Folders';return `<section class="section"><div class="file-actions">${btn(icon('plus')+' Add document','upload','primary')}${btn(icon('edit')+' Write a note','note')}${activeFolder?btn('Rename folder','rename-folder','',`data-id="${esc(activeFolder)}"`):btn(workspace==='education'?'Add subject':'New folder','add-folder')}</div>${showFolders?`<div class="section-top"><h2>${folderTitle}</h2>${workspace==='business'&&!activeFolder?'<small>15 areas</small>':''}</div>${folderGrid(activeFolder)}`:''}${showFolders&&workspace==='business'&&!activeFolder?'<p class="save-note">These areas organize files and tasks. They do not automate payroll or inventory.</p>':''}<div class="section-top"><h2>${activeFolder?'Documents':'All documents'}</h2><small>${files(docs.length)}</small></div><div class="card">${docs.length?docs.map(d=>documentRow(d)).join(''):'<div class="empty">Add a PDF, TXT, or Markdown file, or write a note. Scanned PDFs aren’t supported yet.</div>'}</div>${archivedDocs.length?`<details class="archived-folders archived-documents"><summary>Archived documents <span class="badge">${archivedDocs.length}</span></summary><div class="card">${archivedDocs.map(d=>documentRow(d,true)).join('')}</div></details>`:''}</section>`;}
function tasksView(nested=false){let items=state.tasks.filter(t=>(activeFolder&&nested?t.folder===activeFolder:workspaceFor(t.folder)===workspace)&&(filter==='all'||(filter==='done'?t.done:!t.done)));return `${!nested?workspaceTabs()+'<div class="ws-body '+(anim.ws?'page-enter':'')+'">':''}${!nested?'<div class="heading"><div><h1>Your tasks</h1><p>A little progress, every day.</p></div>'+btn(icon('plus')+' Task','add-task','primary')+'</div>':'<div class="section-top"><h2>Subject checklists</h2>'+btn('+ Task','add-task','primary small')+'</div>'}<div class="task-filters">${[['open','To do'],['done','Completed'],['all','All']].map(([id,label])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</div>${state.folders.filter(f=>items.some(t=>t.folder===f.id)).map(f=>tasksGroup(f.id,items.filter(t=>t.folder===f.id))).join('')||'<div class="card empty">No tasks in this view.</div>'}${!nested?'</div>':''}`;}
function chatView(){const msgs=state.chats[chatKey()]||[];return `<div class="shell chat-shell"><header class="header"><button class="icon-btn" data-action="choose-folder" aria-label="Choose a subject folder">${icon('menu')}</button>${logo()}<button class="icon-btn" data-action="new-chat" aria-label="Start a new chat">${icon('edit')}</button></header><div class="scope"><button class="scope-pill" data-action="choose-folder" aria-label="Choose a folder">${folder(true)}<span>${chatFolder?esc(folderPath(chatFolder))+' · '+WORKSPACES[workspaceFor(chatFolder)].name:'Choose a folder'}</span>${icon('down')}</button></div><main class="chat-body" aria-label="Conversation">${msgs.length?msgs.map((m,i)=>messageHTML(m,i)).join(''):`<div class="chat-empty"><div class="hero-k" aria-hidden="true">K</div><h1>What can I help<br>you with?</h1><p>Ask about the files in ${chatFolder?esc(findFolder(chatFolder)):'a folder'}.</p></div>`}${busy?'<div class="pending" role="status"><span class="dot"></span>Working with your local model…</div>':''}</main>${!msgs.length?'<div class="suggestions"><button data-action="suggest" data-prompt="Summarize the key points in my files.">'+icon('file')+'Summarize a file</button><button data-action="suggest" data-prompt="Explain the main concepts in my files in simple words.">'+icon('help')+'Explain a concept</button></div>':''}<form id="chat-form" class="composer"><button type="button" class="icon-btn" data-action="upload" aria-label="Attach a document">${icon('plus')}</button><textarea id="message" rows="1" aria-label="Message Kusa" placeholder="Message Kusa" maxlength="4000" ${busy?'disabled':''}></textarea><button class="send" aria-label="Send message" ${busy?'disabled':''}>${icon('arrow')}</button></form><p class="chat-help">${lanHost&&!paired?'Open the phone link shown by Kusa on your computer.':localBackend?'Check important details against the sources.':'iPhone preview: connect to Kusa on the computer to use Ask Kusa.'}</p></div>${nav()}`;}
function messageHTML(m,i){return `<div class="bubble ${esc(m.role)} ${m.error?'error':''}">${esc(m.text)}${m.sources?.length?`<div class="sources">${m.sources.map((s,j)=>`<button class="source-btn" data-action="source" data-message="${i}" data-source="${j}">${esc(s.name)} · p. ${s.page}${s.cited?'':' · retrieved'}</button>`).join('')}</div>`:''}${m.tasks?.length?`<div>${btn('Review '+m.tasks.length+' tasks','review','',`data-message="${i}"`)}<small style="display:block">Review before adding to ${esc(findFolder(chatFolder))}.</small></div>`:''}</div>`;}
function settingsView(){
 const ready=!!(localBackend&&status?.connected&&status.models.includes(state.model));
 const connection=!localBackend?'This iPhone install saves its workspace here. TXT and Markdown files can be imported offline; PDF extraction and Ask Kusa need a secure connection to the computer version.':lanHost&&!paired?'Open Kusa with the phone link shown in the computer window to connect this device.':status?.checking?'Checking for local AI…':ready?`Kusa AI is ready · ${esc(state.model)} is available on this computer.`:status?.connected?`Ollama is running, but ${esc(state.model)} is not downloaded yet.`:'Ollama is not connected on this computer yet.';
 return `<div class="settings"><div class="heading"><div><h1>Settings</h1><p>Make this space yours.</p></div></div>
 <section class="card setting-block"><h2>Your workspace</h2><form id="profile-form"><label class="field">Your name<input name="name" value="${esc(state.name)}" maxlength="60" required></label><button class="btn primary">Save name</button></form></section>
 <section class="card setting-block"><h2>Appearance</h2><label class="field">Theme<select id="theme-select"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option><option value="system" ${state.theme==='system'?'selected':''}>Use device setting</option></select></label><p>Your choice is saved on this device.</p></section>
 <section class="card setting-block"><h2>Kusa AI</h2><p>${localBackend?'Kusa checks this computer automatically. After the first setup and model download, Ask Kusa can work without internet.':'This iPhone preview keeps its workspace on this device. Ask Kusa needs a secure connection to a computer, which is not included yet.'}</p><div class="status ai-status ${ready?'ready':''}" id="connection-status" role="status">${connection}</div>
 ${localBackend&&paired?`<div class="backup-actions">${ready?btn(status?.checking?'Checking…':'Check again','check','primary',status?.checking?'disabled':''):btn('Open setup guide','setup-guide','primary')} ${!status?.checking&&!ready?btn('Check again','check','small'):''}</div>${!ready?`<div class="ai-setup-hint"><strong>${status?.connected?'One more step: download the AI model':'Setup takes a few minutes'}</strong><ol><li>${status?.connected?'Open PowerShell.':'Install Ollama from its official website, then open it.'}</li><li>In PowerShell, run <code>ollama pull ${esc(state.model)}</code> and wait for the download to finish.</li><li>Return here and tap <b>Check again</b>. The download needs internet and several GB of free space.</li></ol>${!status?.connected?'<a href="https://ollama.com/download/windows" target="_blank" rel="noopener noreferrer">Get Ollama for Windows</a> · ':''}After setup, the model runs on this computer. Nothing is installed silently.</div>`:''}<details class="ai-advanced"><summary>Advanced · choose a model</summary><form id="model-form"><label class="field">Model name<input name="model" list="models" value="${esc(state.model)}" required maxlength="100"><datalist id="models">${(status?.models||[]).map(m=>`<option value="${esc(m)}">`).join('')}</datalist></label><div class="backup-actions"><button class="btn">Save model</button></div></form><p>Only choose a model that is already downloaded in Ollama. Answers use selected file excerpts; always inspect the sources.</p></details>`:`<p class="inline-help">TXT and Markdown uploads work offline on iPhone. PDF text extraction and Ask Kusa still need a secure connection to Kusa running on your computer.</p>`}</section>
 <section class="card setting-block"><h2>Backup & portability</h2><p>Files, schedules, tasks, and chats are saved in this browser. Export regularly: clearing browser data removes them. Backups contain your document text.</p><div class="backup-actions">${btn(icon('download')+' Export backup','export')}${btn('Import backup','restore')}</div></section>
 <section class="card setting-block"><h2>About this build</h2><p>Kusa v0.10.8 · Solo hackathon edition. Education has subject folders and study sections; Finance and Business have dedicated folders. Documents and folders can be renamed, archived, restored, or deleted. ${localBackend?'PDF text extraction and AI inference run on this computer. Your documents and questions stay on this computer.':'This iPhone preview stores data on this device. AI and server-based file importing need a secure backend connection.'} No external fonts or analytics. Voice, OCR, and cross-device sync are not included.</p>${state.demo?btn('Remove sample content','clear-sample','danger'):''}</section></div>`;
}
function modal(title,body,onSubmit){$('#modal').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${body}`;$('#modal').showModal();if(onSubmit)$('#modal form').onsubmit=onSubmit;}
const actions=(label='Save')=>`<div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">${label}</button></div>`;
function taskForm(id){if(!visibleFolders().length)return toast('Create a folder first.');const task=state.tasks.find(t=>t.id===id)||{title:'',folder:activeFolder||visibleFolders()[0].id,date:'',time:''};modal(id?'Edit task':'New task',`<form><label class="field">Task<input name="title" required maxlength="200" value="${esc(task.title)}"></label><label class="field">Subject<select name="folder">${folderOptions(task.folder)}</select></label><div class="form-grid"><label class="field">Due date (optional)<input type="date" name="date" value="${esc(task.date)}"></label><label class="field">Time (optional)<input type="time" name="time" value="${esc(task.time)}"></label></div>${id?btn('Delete task','delete-task','danger',`data-id="${id}"`):''}${actions()}</form>`,e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(v.time&&!v.date)return toast('Choose a date for this deadline.');if(id)Object.assign(task,v);else state.tasks.push({id:uid(),done:false,...v});persist();$('#modal').close();render();});}
function scheduleForm(id){if(!visibleFolders().length)return toast('Create a folder first.');const s=state.schedule.find(x=>x.id===id)||{title:'',folder:visibleFolders()[0].id,date:today(),start:'09:00',end:'10:00'};modal(id?'Edit schedule':'Add to schedule',`<form><label class="field">Class or event<input name="title" value="${esc(s.title)}" required maxlength="100"></label><label class="field">Subject<select name="folder">${folderOptions(s.folder)}</select></label><label class="field">Date<input type="date" name="date" value="${esc(s.date)}" required></label><div class="form-grid"><label class="field">Starts<input name="start" type="time" value="${esc(s.start)}" required></label><label class="field">Ends<input name="end" type="time" value="${esc(s.end)}" required></label></div>${id?btn('Delete schedule entry','delete-schedule','danger',`data-id="${id}"`):''}${actions()}</form>`,e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(v.end<=v.start)return toast('End time must be after start time.');if(id)Object.assign(s,v);else state.schedule.push({id:uid(),...v});persist();$('#modal').close();render();});}
async function api(path,data){if(!localBackend)throw Error('This iPhone install is not connected to Kusa on the computer.');if(!paired)throw Error('Open the phone link shown in the Kusa computer window to pair this iPhone.');const headers={...(data?{'Content-Type':'application/json'}:{}),...(backendToken?{'X-Kusa-Token':backendToken}:{})};const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers,body:data?JSON.stringify(data):undefined});let body;try{body=await response.json();}catch{throw Error('Start Kusa with start.bat and open http://localhost:8765.');}if(!response.ok)throw Error(body.error||'Request failed.');return body;}
async function send(question){if(busy||!question.trim())return;if(!localBackend)return toast('Ask Kusa needs Kusa running on the computer. Open its phone link on the same Wi-Fi.');if(!paired)return toast('Open the phone link shown in the Kusa computer window to pair this iPhone.');if(routeRequest(question)){$('#message').value='';return;}if(!chatFolder)return toast('Choose a folder first.');const target=chatKey();const docs=state.documents.filter(d=>d.folder===chatFolder&&!d.archived);if(!docs.length)return toast('Add a document or note to this folder first.');const history=[...(state.chats[target]||[])].filter(m=>!m.error);state.chats[target]=state.chats[target]||[];state.chats[target].push({role:'user',text:question.trim()});busy=true;persist();render();try{const result=await api('chat',{question,model:state.model,documents:docs,history:history.slice(-4)});state.chats[target].push({role:'assistant',text:result.answer,tasks:result.tasks,sources:result.sources.map(s=>({...s,cited:result.source_ids.includes(s.id)}))});}catch(e){state.chats[target].push({role:'assistant',text:e.message,error:true});}finally{busy=false;persist();render();}}
function validBackup(x){return x&&x.version===1&&Array.isArray(x.folders)&&x.folders.length<=100&&x.folders.every(f=>typeof f.id==='string'&&/^[a-zA-Z0-9-]+$/.test(f.id)&&typeof f.name==='string')&&['tasks','documents','schedule'].every(k=>Array.isArray(x[k])&&x[k].every(v=>typeof v.id==='string'&&/^[a-zA-Z0-9-]+$/.test(v.id)&&x.folders.some(f=>f.id===v.folder)))&&x.tasks.every(t=>typeof t.title==='string'&&typeof t.done==='boolean'&&typeof t.date==='string'&&typeof t.time==='string')&&x.schedule.every(s=>['title','date','start','end'].every(k=>typeof s[k]==='string'))&&x.documents.every(d=>typeof d.name==='string'&&Array.isArray(d.pages)&&d.pages.every(p=>typeof p.text==='string'&&Number.isInteger(p.number)))&&typeof x.name==='string'&&typeof x.model==='string';}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='nav'){page=el.dataset.page;render();}
 if(a==='workspace'){workspace=el.dataset.workspace;activeFolder=null;chatFolder=visibleFolders()[0]?.id||'';tab='documents';render();}
 if(a==='tab'){tab=el.dataset.tab;render();}
 if(a==='filter'){filter=el.dataset.filter;render();}
 if(a==='open-folder'){activeFolder=id;tab='documents';render();}
 if(a==='back-folders'){activeFolder=activeFolder?(state.folders.find(f=>f.id===activeFolder)?.parentId||null):null;tab='documents';render();}
 if(a==='archive-folder'){const f=state.folders.find(x=>x.id===id);if(f){f.archived=!f.archived;if(folderUnavailable(state.folders.find(x=>x.id===chatFolder)))chatFolder=visibleFolders()[0]?.id||'';if(folderUnavailable(state.folders.find(x=>x.id===activeFolder)))activeFolder=null;persist();render();toast(f.archived?'Folder archived.':'Folder restored.');}}
 if(a==='delete-folder')deleteFolderPrompt(id);
 if(a==='confirm-delete-folder'){const ids=descendantIds(id),hasContents=state.documents.some(x=>ids.includes(x.folder))||state.tasks.some(x=>ids.includes(x.folder))||state.schedule.some(x=>ids.includes(x.folder))||ids.some(folderId=>(state.chats[folderId]||[]).length>0);if(hasContents)confirmPermanentFolderDelete(id);else removeFolder(id,null,true);}
 if(a==='delete-folder-permanently')removeFolder(id,null,true);
 if(a==='close-modal')$('#modal').close();
 if(a==='add-folder'||a==='rename-folder'){const folderId=id||activeFolder;modal(a==='add-folder'?(workspace==='education'?'Add subject':'New folder'):'Rename folder',`<form><label class="field">${workspace==='education'&&a==='add-folder'?'Subject name':'Folder name'}<input name="name" required maxlength="70" value="${a==='rename-folder'?esc(findFolder(folderId)):''}" placeholder="e.g. Mathematics"></label>${actions()}</form>`,event=>{event.preventDefault();const name=new FormData(event.target).get('name').trim();if(!name)return;if(a==='rename-folder'){const f=state.folders.find(f=>f.id===folderId);if(f)f.name=name;}else if(workspace==='education'&&!activeFolder){createEducationSubject(name);}else{const f={id:uid(),name,workspace,parentId:activeFolder||null};state.folders.push(f);if(!chatFolder)chatFolder=f.id;}persist();$('#modal').close();render();});}
 if(a==='add-task'||a==='edit-task')taskForm(id);
 if(a==='add-money'){modal('Add money entry',`<form><label class="field">Type<select name="kind"><option value="expense">Expense</option><option value="income">Income</option></select></label><label class="field">Amount in pesos<input name="amount" type="number" min="0.01" max="999999999" step="0.01" required></label><label class="field">What was it for?<input name="note" maxlength="100" required></label><label class="field">Date<input name="date" type="date" value="${today()}" required></label>${actions()}</form>`,e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));const amount=Number(v.amount);if(!Number.isFinite(amount)||amount<0.01||amount>999999999)return toast('Enter a valid amount.');state.money.push({id:uid(),kind:v.kind,amount:Math.round(amount*100)/100,note:v.note.trim(),date:v.date});persist();$('#modal').close();render();});}
 if(a==='delete-money'){modal('Delete entry?',`<p class="inline-help">This removes the entry from your Finance totals.</p><div class="form-actions">${btn('Cancel','close-modal')}${btn('Delete','confirm-delete-money','danger',`data-id="${esc(id)}"`)}</div>`);}
 if(a==='confirm-delete-money'){state.money=state.money.filter(x=>x.id!==id);persist();$('#modal').close();render();}
 if(a==='add-schedule'||a==='edit-schedule')scheduleForm(id);
 if(a==='delete-task'){state.tasks=state.tasks.filter(t=>t.id!==id);persist();$('#modal').close();render();}
 if(a==='delete-schedule'){state.schedule=state.schedule.filter(s=>s.id!==id);persist();$('#modal').close();render();}
 if(a==='load-demo'){addDemoData();}
 if(a==='quick-upload'){const inbox=state.folders.find(f=>f.workspace==='personal'&&!f.parentId&&!folderUnavailable(f))||state.folders.find(f=>f.workspace==='personal'&&!folderUnavailable(f));if(!inbox)return toast('Create or restore a Personal folder first.');$('#upload').dataset.folder=inbox.id;$('#upload').accept=localBackend?'.pdf,.txt,.md':'.txt,.md';$('#upload').click();}
 if(a==='upload'){if(!visibleFolders().length)return toast('Create or restore a folder first.');modal('Add documents',`<form><p class="inline-help">${localBackend?'Text-based PDF, TXT, or Markdown. Up to 10 MB per file; PDFs up to 100 pages.':'On iPhone offline, choose TXT or Markdown files (up to 1 MB each). PDF text extraction needs the computer version.'}</p><label class="field">Save in folder<select name="folder">${folderOptions(page==='chat'?chatFolder:activeFolder||visibleFolders()[0].id)}</select></label><div class="form-actions"><button class="btn primary">Choose files</button></div></form>`,event=>{event.preventDefault();$('#upload').dataset.folder=new FormData(event.target).get('folder');$('#upload').accept=localBackend?'.pdf,.txt,.md':'.txt,.md';$('#modal').close();$('#upload').click();});}
 if(a==='note'){if(!visibleFolders().length)return toast('Create or restore a folder first.');modal('Write a note',`<form><label class="field">Title<input name="title" required maxlength="100" placeholder="Meeting notes"></label><label class="field">Folder<select name="folder">${folderOptions(activeFolder||visibleFolders()[0].id)}</select></label><label class="field">Your note<textarea name="text" required maxlength="30000" placeholder="Start writing…"></textarea></label>${actions()}</form>`,event=>{event.preventDefault();const v=Object.fromEntries(new FormData(event.target));state.documents.push({id:uid(),folder:v.folder,name:v.title+'.txt',pages:[{number:1,text:v.text}]});persist();$('#modal').close();render();});}
 if(a==='view-doc'){const d=state.documents.find(d=>d.id===id);modal(d.name,`<div class="source-text">${d.pages.map(p=>`<h3>Page ${p.number}</h3>${esc(p.text)}<hr>`).join('')}</div>`);}
 if(a==='rename-document'){const d=state.documents.find(x=>x.id===id);if(d)modal('Rename document',`<form><label class="field">Document name<input name="name" maxlength="140" value="${esc(d.name)}" required></label>${actions()}</form>`,event=>{event.preventDefault();const name=new FormData(event.target).get('name').trim();if(!name)return;if(/[\\/]/.test(name))return toast('Use a document name without slashes.');d.name=name;persist();$('#modal').close();render();});}
 if(a==='archive-document'){const d=state.documents.find(x=>x.id===id);if(d){d.archived=!d.archived;persist();render();toast(d.archived?'Document archived.':'Document restored.');}}
 if(a==='move-doc'){const d=state.documents.find(d=>d.id===id);modal('Move document',`<form><label class="field">Destination workspace and folder<select name="folder">${folderOptions(d.folder,true)}</select></label>${actions('Move')}</form>`,event=>{event.preventDefault();d.folder=new FormData(event.target).get('folder');persist();$('#modal').close();render();toast('Document moved.');});}
 if(a==='delete-doc'){const d=state.documents.find(d=>d.id===id);modal('Delete document?',`<p class="inline-help">Remove ${esc(d.name)} from this workspace? Previous chat excerpts remain in chat history.</p><div class="form-actions">${btn('Cancel','close-modal')}${btn('Delete document','confirm-delete','danger',`data-id="${id}"`)}</div>`);}
 if(a==='confirm-delete'){state.documents=state.documents.filter(d=>d.id!==id);persist();$('#modal').close();render();}
 if(a==='suggest'){const input=$('#message');input.value=el.dataset.prompt;input.focus();}
 if(a==='choose-folder'){modal('Choose a folder',Object.entries(WORKSPACES).map(([id,w])=>{const fs=state.folders.filter(f=>f.workspace===id&&!folderUnavailable(f)&&state.documents.some(d=>d.folder===f.id&&!d.archived));return fs.length?`<div class="pick-group"><small>${esc(w.name)}</small>${fs.map(f=>`<button class="pick-row ${f.id===chatFolder?'active':''}" data-action="pick-chat-folder" data-id="${esc(f.id)}">${folder(true)}<span>${esc(folderPath(f.id))}<small>${files(state.documents.filter(d=>d.folder===f.id&&!d.archived).length)}</small></span></button>`).join('')}</div>`:'';}).join(''));}
 if(a==='pick-chat-folder'){chatFolder=id;workspace=workspaceFor(id);$('#modal').close();render();}
 if(a==='new-chat'){if(busy)return toast('Wait for the current answer to finish.');modal('Start a new chat?',`<p class="inline-help">This clears the saved conversation for this folder. Documents and tasks are kept.</p><div class="form-actions">${btn('Cancel','close-modal')}${btn('Start new chat','confirm-new-chat','primary')}</div>`);}
 if(a==='confirm-new-chat'){state.chats[chatKey()]=[];persist();$('#modal').close();render();}
 if(a==='source'){const s=state.chats[chatKey()][+el.dataset.message].sources[+el.dataset.source];modal(s.name+' · page '+s.page,`<p class="inline-help">${s.cited?'Referenced by the model. Verify that this passage supports the answer.':'Retrieved context sent to the model; not explicitly cited in its answer.'}</p><div class="source-text">${esc(s.text)}</div>`);}
 if(a==='review'){const targetFolder=chatFolder;const m=state.chats[chatKey()][+el.dataset.message];modal('Review suggested tasks',`<form><p class="inline-help">Edit or uncheck items before saving. No deadline will be added automatically.</p><label class="field">Subject<select name="folder">${folderOptions(targetFolder)}</select></label>${m.tasks.map((t,i)=>`<div class="review-row"><input type="checkbox" name="include${i}" checked aria-label="Include task ${i+1}"><input name="task${i}" aria-label="Task ${i+1}" maxlength="200" value="${esc(t)}" required></div>`).join('')}${actions()}</form>`,event=>{event.preventDefault();const values=new FormData(event.target);let count=0;for(let i=0;i<m.tasks.length;i++){const title=values.get('task'+i).trim();if(values.has('include'+i)&&title&&!state.tasks.some(t=>t.folder===values.get('folder')&&t.title===title)){state.tasks.push({id:uid(),title,folder:values.get('folder'),done:false,date:'',time:''});count++;}}persist();$('#modal').close();toast(`${count} tasks saved.`);});}
 if(a==='setup-guide'){const hasOllama=!!status?.connected;modal('Set up Kusa AI',`<p class="inline-help">${hasOllama?'Ollama is installed. Download the model Kusa needs:':'First install Ollama from its official website and open it.'}</p><ol class="setup-steps"><li>${hasOllama?'Open PowerShell.':'Install Ollama for Windows, then open Ollama.'}</li><li>Run <code>ollama pull ${esc(state.model)}</code> and wait for the model download to finish. It can take several minutes and needs internet plus several GB of free space.</li><li>Return to Kusa and choose <b>Check connection</b>. When it says “Kusa AI is ready,” Ask Kusa can use the local model offline.</li></ol>${!hasOllama?'<p><a href="https://ollama.com/download/windows" target="_blank" rel="noopener noreferrer">Download Ollama for Windows</a></p>':''}<p class="inline-help">Kusa will not install apps or download large files without your approval.</p><div class="form-actions"><button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="check">Check connection</button></div>`);}
 if(a==='check'){if(!localBackend||!paired){toast('Open the phone link shown in the Kusa computer window to pair this iPhone.');return;}status={...(status||{}),checking:true};render();try{status=await api('status');}catch{status={connected:false,models:[]};}render();}
 if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='kusa-backup-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 if(a==='restore')$('#restore').click();
 if(a==='clear-sample'){modal('Start with a clean workspace?',`<p class="inline-help">This removes ALL current documents, tasks, schedules, and chats, including anything you added. Export a backup first if needed. Subject folders are kept.</p><div class="form-actions">${btn('Cancel','close-modal')}${btn('Clear workspace','confirm-clear','danger')}</div>`);}
 if(a==='confirm-clear'){if(busy)return toast('Wait for the current answer to finish.');state.documents=[];state.tasks=[];state.schedule=[];state.money=[];state.chats={};state.demo=false;persist();$('#modal').close();render();}
});
document.addEventListener('change',e=>{if(e.target.id==='theme-select'){state.theme=e.target.value;applyTheme();persist();return;}if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===e.target.dataset.task);t.done=e.target.checked;persist();render();}});
document.addEventListener('submit',async e=>{if(e.target.id==='chat-form'){e.preventDefault();send($('#message').value);}if(e.target.id==='profile-form'){e.preventDefault();state.name=new FormData(e.target).get('name').trim()||'Me';persist();render();toast('Name saved.');}if(e.target.id==='model-form'){e.preventDefault();state.model=new FormData(e.target).get('model').trim();persist();toast('Model saved.');}});
document.addEventListener('keydown',e=>{if(e.target.id==='message'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e.target.value);}});
document.addEventListener('pointerdown',e=>{const t=e.target.closest('button,.folder-card,.pick-row,.day-row,.source-btn');if(!t)return;t.classList.remove('glow');void t.offsetWidth;t.classList.add('glow');t.addEventListener('animationend',()=>t.classList.remove('glow'),{once:true});});
$('#upload').addEventListener('change',async e=>{const target=e.target.dataset.folder;const files=[...e.target.files];for(const file of files){try{let pages;if(localBackend){if(file.size>10000000)throw Error('Use files under 10 MB.');toast('Importing '+file.name+'…');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));pages=(await api('extract',{name:file.name,data:btoa(binary)})).pages;}else{if(!/\.(txt|md)$/i.test(file.name))throw Error('Offline iPhone upload supports TXT and Markdown files. PDF text extraction needs the computer version.');if(file.size>1000000)throw Error('For offline iPhone use, choose a text file under 1 MB.');const text=await file.text();if(!text.trim())throw Error('This file has no readable text.');if(text.length>300000)throw Error('This text file is too large for this version. Split it into smaller files.');pages=[{number:1,text}];}const doc={id:uid(),folder:target,name:file.name,pages};state.documents.push(doc);if(!persist()){state.documents.pop();throw Error('Not imported: browser storage is full. Export a backup and remove large files.');}toast(file.name+' imported.');}catch(error){toast(error.message);break;}}e.target.value='';render();});
$('#restore').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Backup must be under 5 MB.');const candidate=JSON.parse(await file.text());if(!validBackup(candidate))throw Error('This is not a supported Kusa backup.');modal('Restore backup?',`<form><p class="inline-help">Replace this workspace with ${candidate.folders.length} folders and ${candidate.documents.length} documents? Export your current workspace first. Chat history is not imported in this version.</p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Restore</button></div></form>`,event=>{event.preventDefault();if(busy)return toast('Wait for the current answer to finish.');const previous=state;state={...candidate,chats:{}};migrate(state);applyTheme();if(!persist()){state=previous;applyTheme();return;}activeFolder=null;chatFolder=visibleFolders()[0]?.id||'';$('#modal').close();render();toast('Workspace restored.');});}catch(error){toast(error.message);}e.target.value='';});
render();persist();if(localBackend&&paired)api('status').then(result=>{status=result;if(page==='settings')render();}).catch(()=>{status={connected:false,models:[]};if(page==='settings')render();});
